<?php

declare(strict_types=1);

namespace App\Service\Bsi;

use Symfony\Component\DependencyInjection\Attribute\Autowire;

/**
 * Reads `fixtures/library/catalogues/bsi-grundschutz-plusplus/reuse_map.json`, generated by
 * `scripts/library/build_gspp_policy_sections.py` from the official BSI mapping
 * ISO/IEC 27001:2022 → Grundschutz++:
 *
 *  - policy topics: ISO policy topic → GS++ requirement IDs (policy wizard section + check)
 *  - practice ISO controls: GS++ practice (GC, BER, KONF, …) → ISO Annex A control IDs,
 *    so the compliance wizard scores a GS++ practice from the tenant's existing SoA.
 */
final class GsppReuseMap
{
    public const string PATH = '/fixtures/library/catalogues/bsi-grundschutz-plusplus/reuse_map.json';

    /** @var array{policy_topics: array<string, list<string>>, practice_iso_controls: array<string, list<string>>}|null */
    private ?array $map = null;

    public function __construct(
        #[Autowire('%kernel.project_dir%')]
        private readonly string $projectDir,
    ) {
    }

    /** @return array<string, list<string>> ISO topic => GS++ requirement IDs */
    public function policyTopics(): array
    {
        return $this->load()['policy_topics'];
    }

    /**
     * ISO Annex A control IDs (Control::controlId format, e.g. `5.15`) the BSI maps to
     * any of the given GS++ practices.
     *
     * @param list<string> $practices
     *
     * @return list<string>
     */
    public function isoControlsFor(array $practices): array
    {
        $controls = [];
        foreach ($practices as $practice) {
            foreach ($this->load()['practice_iso_controls'][$practice] ?? [] as $control) {
                $controls[$control] = true;
            }
        }
        $ids = array_keys($controls);
        natsort($ids);

        return array_values(array_map('strval', $ids));
    }

    /** @return array{policy_topics: array<string, list<string>>, practice_iso_controls: array<string, list<string>>} */
    private function load(): array
    {
        if ($this->map === null) {
            $json = (string) file_get_contents($this->projectDir . self::PATH);
            $this->map = json_decode($json, true, 16, JSON_THROW_ON_ERROR);
        }

        return $this->map;
    }
}
